"use strict";
const api_http = require("./http.js");
const getPropertyGlobalStats = () => api_http.get("/api/slProperty/globalStats");
const getPropertyPage = (input) => api_http.get("/api/slProperty/page", input);
const getPropertyList = (input) => api_http.get("/api/slProperty/list", input);
const getPropertyDetail = (id) => api_http.get("/api/slProperty/detail", { id });
const addProperty = (input) => api_http.post("/api/slProperty/add", input);
const updateProperty = (input) => api_http.post("/api/slProperty/update", input);
const deleteProperty = (input) => api_http.post("/api/slProperty/delete", input);
const updatePropertyStatus = (input) => api_http.post("/api/slProperty/updateStatus", input);
exports.addProperty = addProperty;
exports.deleteProperty = deleteProperty;
exports.getPropertyDetail = getPropertyDetail;
exports.getPropertyGlobalStats = getPropertyGlobalStats;
exports.getPropertyList = getPropertyList;
exports.getPropertyPage = getPropertyPage;
exports.updateProperty = updateProperty;
exports.updatePropertyStatus = updatePropertyStatus;
